-- =====================================================================
-- 10_data.sql — dữ liệu định danh: tài khoản, khu chuồng, ngựa, đơn nhập học, hồ sơ đính kèm.
-- (Identity data: accounts, areas, horses, admissions, attached documents.)
--
-- Sửa dữ liệu ở đây (thêm dòng, đổi tên, đổi ngày); các file sau đọc các bảng tạm này.
-- Mọi ngày giờ viết theo NGÀY GỐC 2026-10-25: khi chạy, seed dời tất cả theo số ngày từ ngày gốc tới hôm nay
-- (hàm pg_temp.d / pg_temp.ts), nên dữ liệu luôn "kết thúc" đúng ngày chạy seed.
-- (Edit data here. Every date is written for the REFERENCE DAY 2026-10-25; the seed shifts all of them by the
-- number of days between that day and today, so the data always ends on the day the seed runs.)
--
-- Tên, UELN, ngày sinh, bố mẹ: tra cứu công khai ANICA. Chủ ngựa, nhân viên, y tế, quy trình: dữ liệu mô phỏng.
-- =====================================================================

-- Tài khoản (Accounts). Mật khẩu của mọi tài khoản: admin123.
CREATE TEMP TABLE seed_account (
    k TEXT PRIMARY KEY, full_name TEXT NOT NULL, email TEXT NOT NULL, role TEXT NOT NULL, phone TEXT, address TEXT,
    created_on DATE NOT NULL, credential TEXT, credential_issued DATE, specialization TEXT, is_active BOOLEAN NOT NULL
);

-- Khu chuồng: mỗi khu 12 chuồng; khu thường có một Head Trainer, khu cách ly (Q) không có.
-- (Areas: 12 stalls each; a regular area has one Head Trainer, a quarantine area none.)
CREATE TEMP TABLE seed_area (code TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL, trainer_k TEXT);

-- Mỗi Groom phụ trách 3 chuồng liền nhau (BR-06: tối đa 3). (Each groom looks after 3 consecutive stalls.)
CREATE TEMP TABLE seed_groom_block (groom_k TEXT PRIMARY KEY, area_code TEXT NOT NULL, first_stall INT NOT NULL);

-- Hồ sơ ngựa như chủ ngựa khai khi nộp đơn (ảnh chụp bất biến). (Horse profile as the owner submitted it.)
-- vaccinations / dewormings: các mũi đã tiêm trước khi tới, Thú y nhập lại lúc khám nhập trại.
-- (Doses given before arrival; the vet enters them as history during the intake exam.)
CREATE TEMP TABLE seed_horse (
    k TEXT PRIMARY KEY, name TEXT NOT NULL, ueln TEXT NOT NULL, registry TEXT, breed TEXT, dob DATE, sex TEXT NOT NULL,
    sire_name TEXT, sire_ueln TEXT, dam_name TEXT, dam_ueln TEXT, pedigree_notes TEXT, owner_k TEXT NOT NULL,
    folder TEXT NOT NULL, exam_temp NUMERIC, exam_hr NUMERIC, exam_rr NUMERIC, vaccinations DATE[], dewormings DATE[]
);

-- File đính kèm của từng đơn. file_url là khóa lưu trữ thật: URL Cloudinary (private, không chữ ký) của file đã upload
-- sẵn khi seed cloud ngày 17/10; backend ký lại khi đọc (FileStorageService), nên máy nào có CLOUDINARY_URL cùng tài khoản đều mở được.
-- (Files of each admission. file_url is the stored key: the private Cloudinary URL of the file already uploaded by the
-- 17 Oct cloud seed; the backend signs it when reading, so any machine with the same CLOUDINARY_URL can open it.)
CREATE TEMP TABLE seed_doc (horse_k TEXT NOT NULL, ord INT NOT NULL, doc_type TEXT NOT NULL, file_url TEXT NOT NULL,
    file_name TEXT NOT NULL, record_date DATE, note TEXT, PRIMARY KEY (horse_k, ord));

-- Đơn nhập học và kết quả từng bước. Ngày giờ theo ngày gốc. NULL = bước chưa diễn ra.
-- groom_k / vet_k / trainer_k: người xử lý; vet_decision BLOCKED = Thú y cho tạm nghỉ, kèm restriction và lịch tái khám.
-- no_history = Thú y không nhập mũi tiêm cũ lúc khám nhập trại.
-- (Admissions and the outcome of each step. NULL = step not reached yet.)
CREATE TEMP TABLE seed_admission (
    k TEXT PRIMARY KEY, horse_k TEXT NOT NULL, owner_k TEXT NOT NULL, status TEXT NOT NULL, submitted TIMESTAMP NOT NULL,
    groom_k TEXT, groom_at TIMESTAMP, groom_decision TEXT, q_stall TEXT, arrived TIMESTAMP,
    vet_k TEXT, vet_decision TEXT NOT NULL DEFAULT 'ALLOWED', restriction TEXT, no_history BOOLEAN NOT NULL DEFAULT FALSE,
    trainer_k TEXT, trainer_at TIMESTAMP, readiness TEXT, conformation NUMERIC, temperament NUMERIC, gait NUMERIC,
    months_to_race INT, manager_at TIMESTAMP, manager_decision TEXT, regular_stall TEXT
);

